#!/usr/bin/env python3
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[1]
SRC = ROOT / 'public_suffix_list.dat'
OUT = ROOT / 'public-suffix.js'

def ascii_domain(rule: str) -> str:
    parts = []
    for label in rule.split('.'):
        if label == '*':
            parts.append(label)
        else:
            parts.append(label.encode('idna').decode('ascii').lower())
    return '.'.join(parts)

exact, wildcard, exception = [], [], []
for raw in SRC.read_text(encoding='utf-8').splitlines():
    line = raw.strip()
    if not line or line.startswith('//'):
        continue
    if line.startswith('!'):
        exception.append(ascii_domain(line[1:]))
    elif line.startswith('*.'):
        wildcard.append(ascii_domain(line[2:]))
    else:
        exact.append(ascii_domain(line))

exact = sorted(set(exact))
wildcard = sorted(set(wildcard))
exception = sorted(set(exception))

header = '''/*\n * WebClip bundled Public Suffix List resolver.\n * Source data: https://publicsuffix.org/list/public_suffix_list.dat\n * Generated by project_tools/build_public_suffix_js.py.\n * Public Suffix List data is maintained by the publicsuffix.org project.\n * Do not edit generated rule arrays manually.\n */\n'''
code = header + f'''(() => {{\n  'use strict';\n  const EXACT = new Set({json.dumps(exact, ensure_ascii=False, separators=(',', ':'))});\n  const WILDCARD_BASE = new Set({json.dumps(wildcard, ensure_ascii=False, separators=(',', ':'))});\n  const EXCEPTION = new Set({json.dumps(exception, ensure_ascii=False, separators=(',', ':'))});\n\n  function normalizeHostname(value) {{\n    let raw = String(value || '').trim().toLowerCase().replace(/^\\.+|\\.+$/g, '');\n    if (!raw) return '';\n    try {{\n      const candidate = raw.includes('://') ? raw : `http://${{raw}}`;\n      raw = new URL(candidate).hostname.toLowerCase().replace(/^\\.+|\\.+$/g, '');\n    }} catch (_) {{\n      raw = raw.replace(/^https?:\\/\\//i, '').split('/')[0].split(':')[0].toLowerCase().replace(/^\\.+|\\.+$/g, '');\n    }}\n    return raw;\n  }}\n\n  function isIpLike(host) {{\n    if (!host) return false;\n    if (host.startsWith('[') && host.endsWith(']')) return true;\n    if (host.includes(':')) return true;\n    const parts = host.split('.');\n    return parts.length === 4 && parts.every((part) => /^\\d{{1,3}}$/.test(part) && Number(part) <= 255);\n  }}\n\n  function publicSuffixLabelCount(hostname) {{\n    const host = normalizeHostname(hostname);\n    if (!host || isIpLike(host)) return 0;\n    const labels = host.split('.').filter(Boolean);\n    if (labels.length <= 1) return labels.length;\n\n    // Exception rules override wildcard/exact matches. For !city.kawasaki.jp\n    // the public suffix is kawasaki.jp (one label shorter than the rule).\n    for (let start = 0; start < labels.length; start += 1) {{\n      const suffix = labels.slice(start).join('.');\n      if (EXCEPTION.has(suffix)) return Math.max(1, labels.length - start - 1);\n    }}\n\n    let best = 1; // implicit '*' rule\n    for (let start = 0; start < labels.length; start += 1) {{\n      const suffix = labels.slice(start).join('.');\n      if (EXACT.has(suffix)) best = Math.max(best, labels.length - start);\n      if (start > 0 && WILDCARD_BASE.has(suffix)) best = Math.max(best, labels.length - start + 1);\n    }}\n    return Math.min(labels.length, best);\n  }}\n\n  function hierarchy(value) {{\n    const host = normalizeHostname(value);\n    if (!host) return {{ host: '', publicSuffix: '', base: '', third: '' }};\n    if (isIpLike(host)) return {{ host, publicSuffix: host, base: host, third: host }};\n    const labels = host.split('.').filter(Boolean);\n    if (labels.length === 1) return {{ host, publicSuffix: host, base: host, third: host }};\n    const suffixCount = publicSuffixLabelCount(host);\n    if (!suffixCount || labels.length <= suffixCount) return {{ host, publicSuffix: host, base: host, third: host }};\n    const baseCount = suffixCount + 1;\n    const base = labels.slice(-baseCount).join('.');\n    const third = labels.length > baseCount ? labels.slice(-(baseCount + 1)).join('.') : base;\n    return {{ host, publicSuffix: labels.slice(-suffixCount).join('.'), base, third }};\n  }}\n\n  function siteKey(value) {{ return hierarchy(value).third; }}\n\n  globalThis.WebClipPublicSuffix = Object.freeze({{\n    normalizeHostname,\n    publicSuffixLabelCount,\n    hierarchy,\n    siteKey,\n    ruleCounts: Object.freeze({{ exact: EXACT.size, wildcard: WILDCARD_BASE.size, exception: EXCEPTION.size }})\n  }});\n}})();\n'''
OUT.write_bytes(code.encode('utf-8'))
print(f'Wrote {OUT.name}: exact={len(exact)} wildcard={len(wildcard)} exception={len(exception)} bytes={OUT.stat().st_size}')
